use vstd::prelude::*;

verus! {

fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>)
    ensures
        // we return exactly ny rows in each grid
        result.0.len() == y.len(),
        result.1.len() == y.len(),
        // each row of x_grid is exactly a clone of x
        forall |i: usize| i < y.len() ==> result.0[i] == x,
        // each row of y_grid has length equal to x.len(),
        // and each entry in row i is exactly y[i]
        forall |i: usize|
            i < y.len() ==>
                result.1[i].len() == x.len() &&
                forall |j: usize| j < x.len() ==> result.1[i][j] == y[i],
{
    let nx = x.len();
    let ny = y.len();

    // allocate empty grids with capacity ny
    let mut x_grid: Vec<Vec<f32>> = Vec::with_capacity(ny);
    let mut y_grid: Vec<Vec<f32>> = Vec::with_capacity(ny);

    // a little ghost index so we know which element of y we're on
    ghost let mut idx: usize = 0;

    // iterate over all &yi in &y
    for &yi in &y
        invariant
            // idx always tells us how many we've processed
            idx <= ny,
            idx == x_grid.len(),
            // the two grids grow in lock‐step
            x_grid.len() == y_grid.len(),
            // for every row k we've already pushed, x_grid[k] == x
            forall |k: usize| k < x_grid.len() ==> x_grid[k] == x,
            // and for every row k < y_grid.len(), that row has length nx
            // and each entry is exactly y[k]
            forall |k: usize|
                k < y_grid.len() ==>
                    y_grid[k].len() == nx &&
                    forall |j: usize| j < nx ==> y_grid[k][j] == y[k],
        decreases
            ny - idx
    {
        // prove that this is in fact the k‐th element of y that we're
        // replicating.
        ghost {
            assert(yi == y[idx]);
        }

        // push a clone of x
        x_grid.push(x.clone());
        // push a vec![yi; nx]
        y_grid.push(vec![yi; nx]);

        // advance our ghost index
        ghost {
            idx += 1;
        }
    }

    (x_grid, y_grid)
}

} // end verus!